class Truncate(Step):
    def __init__(self, length: int):
        self._length = length

    def apply(self, text: str) -> str:
        return text[: self._length]


class Squeeze(Step):

"""Which name means which step."""

from pipeline.steps import Squeeze, Strip, Truncate, Upper

STEPS = {"upper": Upper(), "strip": Strip(), "squeeze": Squeeze()}


def lookup(name: str):
    if ":" in name:
        parts = name.split(":", 1)
        step_name = parts[0]
        arg = parts[1]
        if step_name == "truncate":
            if arg == "":
                raise ValueError(f"truncate requires a length, got {name!r}")
            try:
                length = int(arg)
            except ValueError:
                raise ValueError(f"truncate length must be an integer, got {arg!r}")
            return Truncate(length)
        raise KeyError(f"no step named {step_name!r}. Known: {', '.join(sorted(STEPS))}")
    if name not in STEPS:
        raise KeyError(f"no step named {name!r}. Known: {', '.join(sorted(STEPS))}")
    return STEPS[name]

